-- ============================================================
--  UniGrant — Stored Procedures, Events & Backup Strategy
--  Owner: Chaitrali Shrikant Dharmadhikari (backup notes: Arnav Gupta)
-- ============================================================
--  Responsibilities:
--    • Stored procedure: generate_annual_report(dept_id)
--    • Scheduled event: milestone_30day_alert (daily notification)
--    • Scheduled event: monthly_budget_snapshot (analytics archive)
--    • Backup strategy documentation (mysqldump commands)
--    • Point-in-time recovery (binary log) guidelines
-- ============================================================

USE unigrant;

-- Enable MySQL event scheduler (must be ON for events to fire)
SET GLOBAL event_scheduler = ON;

DELIMITER //

-- ════════════════════════════════════════════════════════════
--  STORED PROCEDURE: generate_annual_report
--  Purpose: Generate a comprehensive annual report for a given
--           department — funding received, projects, outputs,
--           students supported, and budget utilisation %.
--  Caller:  GET /api/reports/department/:id (DBA console)
--  SQL:     CALL generate_annual_report(dept_id);
-- ════════════════════════════════════════════════════════════
CREATE PROCEDURE generate_annual_report(IN p_dept_id INT)
BEGIN
  DECLARE dept_exists INT DEFAULT 0;

  -- Input validation (mirrors CHECK constraint in application)
  SELECT COUNT(*) INTO dept_exists
  FROM Department WHERE dept_id = p_dept_id;

  IF dept_exists = 0 THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'ERR-DEPT001: Department not found';
  END IF;

  -- Reuses Admin_Analytics_View, whose measures are pre-aggregated per
  -- department. Expenditure is a separate subquery for the same reason:
  -- joining Expense to the other tables would multiply the rows.
  SELECT
    a.dept_name,
    YEAR(CURDATE())           AS report_year,
    a.total_funding           AS total_funds_received,
    a.total_projects,
    a.active_projects,
    a.completed_projects,
    a.total_research_outputs,
    a.publications,
    a.patents,
    a.students_supported,
    x.total_expenditure,
    ROUND(x.total_expenditure / NULLIF(a.total_funding, 0) * 100, 2) AS budget_utilisation_pct
  FROM Admin_Analytics_View a
  CROSS JOIN (
    SELECT IFNULL(SUM(e.amount), 0) AS total_expenditure
    FROM Expense e
    JOIN Project p ON e.project_id = p.project_id
    WHERE p.department_id = p_dept_id AND e.status = 'Approved'
  ) x
  WHERE a.dept_id = p_dept_id;
END //

-- ════════════════════════════════════════════════════════════
--  STORED PROCEDURE: get_pi_budget_summary
--  Purpose: Return budget utilisation per project for a given PI.
--  SQL:     CALL get_pi_budget_summary(pi_user_id);
-- ════════════════════════════════════════════════════════════
CREATE PROCEDURE get_pi_budget_summary(IN p_pi_id INT)
BEGIN
  SELECT
    p.project_id,
    p.project_title,
    bh.category,
    bh.allocated_amount,
    bh.spent_amount,
    bh.remaining_balance,
    ROUND(bh.spent_amount / NULLIF(bh.allocated_amount, 0) * 100, 1) AS utilisation_pct
  FROM Project     p
  JOIN BudgetHead  bh ON p.project_id = bh.project_id
  WHERE p.pi_id = p_pi_id
  ORDER BY p.project_id, bh.category;
END //

DELIMITER ;

-- ════════════════════════════════════════════════════════════
--  SCHEDULED EVENT 1: milestone_30day_alert
--  Schedule: Daily at midnight
--  Purpose:  Insert a Notification row for PIs whose milestones
--            are due in exactly 30 days (mirrors the 30-day
--            urgency colouring on the Milestones screen).
-- ════════════════════════════════════════════════════════════
CREATE EVENT IF NOT EXISTS milestone_30day_alert
ON SCHEDULE EVERY 1 DAY
STARTS CURDATE()
DO
  SELECT
    p.pi_id,
    CONCAT('⚠ Milestone due in 30 days: "', m.title,
           '" for project: ', p.project_title,
           ' — Deliverable: ', IFNULL(m.deliverable_description, 'N/A')),
    NOW()
  FROM Milestone m
  JOIN Project p ON m.project_id = p.project_id
  WHERE m.status   = 'Pending'
    AND m.due_date = DATE_ADD(CURDATE(), INTERVAL 30 DAY);

-- ════════════════════════════════════════════════════════════
--  SCHEDULED EVENT 2: monthly_budget_snapshot
--  Schedule: 1st of every month
--  Purpose:  Archive current BudgetHead balances for trend analysis
--            and audit trail. Creates a snapshot in BudgetSnapshot.
-- ════════════════════════════════════════════════════════════

-- Snapshot archive table (created once)
CREATE TABLE IF NOT EXISTS BudgetSnapshot (
  snapshot_id    INT            NOT NULL AUTO_INCREMENT,
  snapshot_date  DATE           NOT NULL,
  budgethead_id  INT            NOT NULL,
  project_id     INT            NOT NULL,
  category       VARCHAR(20)    NOT NULL,
  allocated_amount DECIMAL(15,2),
  spent_amount     DECIMAL(15,2),
  remaining_balance DECIMAL(15,2),
  PRIMARY KEY (snapshot_id),
  INDEX IDX_Snapshot_Date (snapshot_date)
);

CREATE EVENT IF NOT EXISTS monthly_budget_snapshot
ON SCHEDULE EVERY 1 MONTH
STARTS DATE_ADD(LAST_DAY(CURDATE()), INTERVAL 1 DAY)
DO
     allocated_amount, spent_amount, remaining_balance)
  SELECT
    CURDATE(),
    bh.budgethead_id,
    bh.project_id,
    bh.category,
    bh.allocated_amount,
    bh.spent_amount,
    bh.remaining_balance
  FROM BudgetHead bh
  JOIN Project p ON bh.project_id = p.project_id
  WHERE p.status = 'Active';

-- ════════════════════════════════════════════════════════════
--  SCHEDULED EVENT 3: grant_closure_check
--  Schedule: Daily
--  Purpose:  Automatically mark grants as 'Closed' when their
--            end_date has passed (complements auto_close_project trigger).
-- ════════════════════════════════════════════════════════════
CREATE EVENT IF NOT EXISTS grant_closure_check
ON SCHEDULE EVERY 1 DAY
STARTS CURDATE()
DO
  UPDATE Grant_
  SET status = 'Closed'
  WHERE status   = 'Active'
    AND end_date < CURDATE();

-- ════════════════════════════════════════════════════════════
--  BACKUP & RECOVERY STRATEGY
-- ════════════════════════════════════════════════════════════

-- ── Full logical backup (mysqldump) ───────────────────────────
-- Run nightly via cron. Produces SQL dump for point-in-time restore.
--
-- $ mysqldump -u admin_user -p unigrant \
--     --single-transaction \
--     --routines \
--     --triggers \
--     --events \
--     --hex-blob \
--   > /backups/unigrant_$(date +%Y%m%d_%H%M%S).sql
--
-- --single-transaction: uses InnoDB snapshot, no table locks
-- --routines:           includes stored procedures
-- --triggers:           includes all trigger definitions
-- --events:             includes scheduled events

-- ── Incremental backup (binary log) ──────────────────────────
-- Enable binary logging in my.cnf:
--   [mysqld]
--   log_bin = /var/log/mysql/binlog
--   binlog_format = ROW
--   expire_logs_days = 7
--
-- Point-in-time recovery to T (after restoring full dump):
--   $ mysqlbinlog --start-datetime="2025-01-01 00:00:00" \
--                 --stop-datetime="2025-01-15 14:30:00" \
--                 /var/log/mysql/binlog.000001 | mysql -u root -p unigrant

-- ── Backup verification (weekly) ──────────────────────────────
-- Restore to a test instance and verify row counts:
--   $ mysql -u admin_user -p unigrant_test < /backups/unigrant_latest.sql
--   $ mysql -u admin_user -p -e \
--       "SELECT TABLE_NAME, TABLE_ROWS FROM information_schema.TABLES
--        WHERE TABLE_SCHEMA='unigrant_test';"

-- ── Replication setup (High Availability) ─────────────────────
-- Primary-Replica setup for read scaling:
--   On primary:  GRANT REPLICATION SLAVE ON *.* TO 'replica_user'@'replica_host';
--   On replica:  CHANGE MASTER TO MASTER_HOST='primary_host',
--                  MASTER_USER='replica_user', MASTER_AUTO_POSITION=1;
--                START SLAVE;

-- ============================================================
--  END: schema/05_stored_procs_events.sql
